<section class="container section"><div class="section-head"><div><p class="eyebrow">GESTIÓN DEPORTIVA</p><h1>Integrantes</h1></div><?php if(\App\Services\Security::user()['rol']==='administrador'): ?><a class="button" href="<?= e(url('registro')) ?>">Inscribir jugador +</a><?php endif; ?></div>
<form class="filters" method="get" action="<?= e(config()['base_path']) ?>/index.php"><input type="hidden" name="r" value="equipo"><div><label for="q">Buscar por nombre o correo</label><input id="q" name="q" maxlength="100" value="<?= e($query) ?>"></div><div><label for="estado">Inscripción</label><select id="estado" name="estado"><option value="">Todos los estados</option><?php foreach(['pendiente'=>'Pendiente','en_revision'=>'En revisión','activa'=>'Activa','rechazada'=>'Rechazada','retirada'=>'Retirada'] as $k=>$v): ?><option value="<?= e($k) ?>" <?= $state===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></div><button type="submit" class="button">Buscar</button></form>
<?php if(!$rows): ?><p class="empty">No hay integrantes que coincidan con la búsqueda.</p><?php else: ?><div class="table-wrap" role="region" aria-label="Integrantes" tabindex="0"><table><thead><tr><th>Jugador</th><th>Categoría</th><th>Inscripción</th><th>Acceso</th><th>Ficha</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= e($row['nombre']) ?></strong><br><small><?= e($row['correo']) ?></small></td><td><?= e($row['categoria']??'Sin asignar') ?></td><td><span class="badge"><?= e(str_replace('_',' ',$row['estado'])) ?></span></td><td><?= $row['activo']?'Habilitado':'Deshabilitado' ?></td><td><a href="<?= e(url('equipo/ficha',['id'=>$row['id']])) ?>">Abrir ficha</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<div class="actions pager"><?php if($page>1): ?><a href="<?= e(url('equipo',['page'=>$page-1,'q'=>$query,'estado'=>$state])) ?>">Anterior</a><?php endif; ?><?php if($more): ?><a href="<?= e(url('equipo',['page'=>$page+1,'q'=>$query,'estado'=>$state])) ?>">Siguiente</a><?php endif; ?></div></section>
